const newItems = items.map(item => {
  // Создаём копию входящего объекта
  const newItem = { json: { ...item.json } };

  // Проверяем, что output - строка, и пытаемся распарсить её в объект
  if (typeof newItem.json.output === 'string') {
    try {
      newItem.json.output = JSON.parse(newItem.json.output);
    } catch (e) {
      // Если парсинг не удался, сохраняем сообщение об ошибке
      newItem.json.output = { error: "Ошибка парсинга JSON: " + e.message };
    }
  }

  return newItem;
});

return newItems;

